    # Renders one of the icons above. Size and colour come from the utility
    # classes passed in: the icon itself inherits currentColor.
    def icon(name, css_class: "size-5", title: nil)
      markup = ICONS[name.to_s]
      return unless markup

      tag.svg(
        safe_join([ (tag.title(title) if title.present?), markup.html_safe ].compact),
        class: css_class,
        xmlns: "http://www.w3.org/2000/svg",
        fill: "none",
        viewBox: "0 0 24 24",
        "stroke-width": 1.5,
        stroke: "currentColor",
        "aria-hidden": title.blank?,
        role: ("img" if title.present?)
      )
    end
  end
